#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/mise/tasks/code-lint-bootstrap.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Validate the values in .config/bootstrap/ with bootstrap check"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}

# USAGE flag "--all" help="check when the values folder has a file, not only an uncommitted one"
# USAGE flag "--debug" help="emit debug logs"
# USAGE flag "--fix" help="accepted and ignored: the check has no fixes"
# USAGE arg "[files]" var=#true help="the files to lint; the check runs when one is a file of .config/bootstrap/; the default is the uncommitted files"
# FILES include=".config/bootstrap/*.toml" exclude=".config/bootstrap/config-files.toml"

import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402

# The origins of a clone of bootstrap.
ORIGINS = (
  "https://github.com/virajp/bootstrap.git",
  "https://github.com/virajp/bootstrap",
  "git@github.com:virajp/bootstrap.git",
  "git@github.com:virajp/bootstrap",
  "ssh://git@github.com/virajp/bootstrap.git",
)


def check(gate):
  # Without bootstrap, the task does not apply and prints nothing. BOOTSTRAP_BIN,
  # a local build, replaces the bootstrap of mise.
  if os.environ.get("BOOTSTRAP_BIN", ""):
    binary = [os.environ["BOOTSTRAP_BIN"]]
  else:
    if not helpers.has_tool("bootstrap"):
      return 0
    binary = ["mise", "x", "--", "bootstrap"]
  os.chdir(os.environ["MISE_PROJECT_ROOT"])

  # The check examines the whole values folder. It runs only when the list of
  # gate_files (the # FILES header above) has a file: with no file, the gate
  # does not apply and prints nothing.
  args = []
  for flag in ("all", "debug", "fix"):
    if os.environ.get(f"usage_{flag}", "false") == "true":
      args.append(f"--{flag}")
  listing = helpers.gate_files(gate, *args, *helpers.usage_files())
  try:
    if os.path.getsize(listing) == 0:
      return 0

    # The gate never uses the network: it reads the shared cache clone of
    # bootstrap, without its lock, and it never fetches. Without that clone, the
    # gate does not apply and prints nothing. A fetch at the same time is rare,
    # and the next commit runs the gate again.
    cache = os.environ.get("BOOTSTRAP_CACHE", "")
    if not cache:
      cache = f"{os.environ.get('XDG_CACHE_HOME', '') or os.path.expanduser('~/.cache')}/bootstrap"
    repo = f"{cache}/repo"
    if not os.path.isfile(f"{repo}/cli/VERSION"):
      return 0

    # Only a clone of bootstrap. The config file itself, because a git hook sets
    # GIT_DIR to the consumer. Any other origin: the gate does not apply and prints
    # nothing.
    result = subprocess.run(
      ["git", "config", "--file", f"{repo}/.git/config", "--get", "remote.origin.url"],
      check=False,
      stdout=subprocess.PIPE,
      stderr=subprocess.DEVNULL,
      text=True,
    )
    origin = result.stdout.rstrip("\n") if result.returncode == 0 else ""
    if origin not in ORIGINS:
      return 0

    helpers.print_header("Validating .config/bootstrap/ ...")

    # A git hook exports these, and the check must examine this repository.
    env = {k: v for k, v in os.environ.items() if k not in ("GIT_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE")}
    env["BOOTSTRAP_CLONE"] = repo
    rc = subprocess.run([*binary, "check"], check=False, env=env).returncode
    return 128 - rc if rc < 0 else rc
  finally:
    os.remove(listing)


if __name__ == "__main__":
  sys.exit(check(os.path.abspath(__file__)))
